302	async fn forward_lora_openai_request(
303	    State(state): State<LoraOpenAiState>,
304	    request: Request,
305	) -> Response {
306	    match forward_lora_openai_request_inner(state, request).await {
307	        Ok(response) => response,
308	        Err(error) => (
309	            StatusCode::BAD_REQUEST,
310	            Json(ErrorBody {
311	                error: format!("failed to prepare LoRA request: {error:#}"),
312	            }),
313	        )
314	            .into_response(),
315	    }
316	}
317	
318	async fn forward_lora_openai_request_inner(
319	    state: LoraOpenAiState,
320	    request: Request,
321	) -> Result<Response> {
322	    let (mut parts, body) = request.into_parts();
323	    let mut body = to_bytes(body, LORA_ROUTE_BODY_LIMIT)
324	        .await
325	        .context("failed to read OpenAI request body")?;
326	    let _ =
327	        rewrite_lora_request_body(&mut body, &state.base_model_name, &state.adapter_names).await?;
328	    parts.headers.insert(
329	        CONTENT_LENGTH,
330	        HeaderValue::from_str(&body.len().to_string())
331	            .context("rewritten body length is invalid")?,
332	    );
333	
334	    state
335	        .vllm_router
336	        .oneshot(Request::from_parts(parts, Body::from(body)))
337	        .await
338	        .context("vLLM router failed to handle LoRA request")
339	}
340	
341	async fn rewrite_lora_request_body(
342	    body: &mut Bytes,
343	    base_model_name: &str,
344	    adapter_names: &Arc<RwLock<HashSet<String>>>,
345	) -> Result<Option<String>> {
346	    let mut value: serde_json::Value =
347	        serde_json::from_slice(body).context("failed to parse OpenAI request JSON")?;
348	    let Some(model) = value.get("model").and_then(serde_json::Value::as_str) else {
349	        return Ok(None);
350	    };
351	    if model == base_model_name {
352	        return Ok(None);
353	    }
354	    if !adapter_names.read().await.contains(model) {
355	        return Ok(None);
356	    }
357	    let adapter = model.to_string();
358	    value["model"] = serde_json::Value::String(base_model_name.to_string());
359	    let Some(map) = value.as_object_mut() else {
360	        return Ok(None);
361	    };
362	    let xargs = map
363	        .entry("vllm_xargs")
364	        .or_insert_with(|| serde_json::Value::Object(serde_json::Map::new()));
365	    if !xargs.is_object() {
366	        *xargs = serde_json::Value::Object(serde_json::Map::new());
367	    }
368	    xargs
369	        .as_object_mut()
370	        .expect("vllm_xargs must be object")
371	        .insert(
372	            LORA_ADAPTER_XARG.to_string(),
373	            serde_json::Value::String(adapter.clone()),
374	        );
375	    *body = Bytes::from(serde_json::to_vec(&value)?);
376	    Ok(Some(adapter))
377	}
