1	//! The pegainfer server binary: pure dispatch over the compiled-in
2	//! [`ModelLine`]s. Every model-specific flag, rule, and option type lives in
3	//! its model crate; this file only wires detection, CLI validation, and the
4	//! serve path selection together.
5	
6	use std::time::Instant;
7	
8	use anyhow::Context;
9	use clap::FromArgMatches;
10	use log::info;
11	use pegainfer_core::logging;
12	use pegainfer_frontend::engine::LaunchedEngine;
13	use pegainfer_frontend::model_line::DetectError;
14	use pegainfer_frontend::model_line::LaunchContext;
15	use pegainfer_frontend::model_line::ModelLine;
16	use pegainfer_frontend::model_line::ModelLineRegistry;
17	use pegainfer_frontend::model_line::SharedArgs;
18	use pegainfer_frontend::model_line::provided_args;
19	
20	#[cfg(not(target_env = "msvc"))]
21	#[global_allocator]
22	static GLOBAL: tikv_jemallocator::Jemalloc = tikv_jemallocator::Jemalloc;
23	
24	fn model_lines() -> Vec<&'static dyn ModelLine> {
25	    vec![
26	        #[cfg(feature = "deepseek-v2-lite")]
27	        &pegainfer_deepseek_v2_lite::model_line::MODEL_LINE,
28	        #[cfg(feature = "gemma4")]
29	        &pegainfer_gemma4::model_line::MODEL_LINE,
30	        #[cfg(feature = "glm52")]
31	        &pegainfer_glm52::model_line::MODEL_LINE,
32	        #[cfg(feature = "k3")]
33	        &pegainfer_k3::model_line::MODEL_LINE,
34	        #[cfg(feature = "kimi-k2")]
35	        &pegainfer_kimi_k2::model_line::MODEL_LINE,
36	        #[cfg(feature = "qwen3")]
37	        &pegainfer_qwen3::model_line::MODEL_LINE,
38	        #[cfg(feature = "qwen35")]
39	        &pegainfer_qwen35::model_line::MODEL_LINE,
40	        #[cfg(feature = "qwen4")]
41	        &pegainfer_qwen4::model_line::MODEL_LINE,
42	    ]
43	}
44	
45	/// One row of [`families`]: a line's feature, the identities its `probe` claims,
46	/// and whether that line is compiled into this binary.
47	struct Family {
48	    feature: &'static str,
49	    model_types: &'static [&'static str],
50	    text_model_types: &'static [&'static str],
51	    compiled: bool,
52	}
53	
54	/// Every line the server can be built with, and the identities its `probe`
55	/// claims.
