302	async fn forward_lora_openai_request(
303	    State(state): State<LoraOpenAiState>,
304	    request: Request,
305	) -> Response {
306	    match forward_lora_openai_request_inner(state, request).await {
307	        Ok(response) => response,
308	        Err(error) => (
309	            StatusCode::BAD_REQUEST,
310	            Json(ErrorBody {
