318	async fn forward_lora_openai_request_inner(
319	    state: LoraOpenAiState,
320	    request: Request,
321	) -> Result<Response> {
322	    let (mut parts, body) = request.into_parts();
323	    let mut body = to_bytes(body, LORA_ROUTE_BODY_LIMIT)
324	        .await
325	        .context("failed to read OpenAI request body")?;
326	    let _ =
327	        rewrite_lora_request_body(&mut body, &state.base_model_name, &state.adapter_names).await?;
328	    parts.headers.insert(
329	        CONTENT_LENGTH,
330	        HeaderValue::from_str(&body.len().to_string())
331	            .context("rewritten body length is invalid")?,
332	    );
333	
334	    state
335	        .vllm_router
336	        .oneshot(Request::from_parts(parts, Body::from(body)))
337	        .await
338	        .context("vLLM router failed to handle LoRA request")
339	}
