379	async fn lora_models_response(
380	    served_model_names: &[String],
381	    base_model_name: &str,
382	    adapter_names: &Arc<RwLock<HashSet<String>>>,
383	) -> Response {
384	    let mut ids: Vec<String> = if served_model_names.is_empty() {
385	        vec![base_model_name.to_string()]
386	    } else {
387	        served_model_names.to_vec()
388	    };
389	    ids.extend(adapter_names.read().await.iter().cloned());
390	    ids.sort();
391	    ids.dedup();
392	    Json(ModelListBody {
393	        object: "list",
394	        data: ids
395	            .into_iter()
396	            .map(|id| ModelCardBody {
397	                id,
398	                object: "model",
399	                created: 0,
400	                owned_by: "vllm-frontend-rs",
401	            })
402	            .collect(),
403	    })
404	    .into_response()
405	}
