        // the prefilling queue; splicing them back at the front (in step
        // order, which is request-id order) keeps the queue FIFO so chunked
        // prompts finish before newer arrivals start.
        let mut continued: Vec<PendingRequest> = Vec::new();
        for effect in effects.pending {
            match effect {
                PendingEffect::ContinuePrefill { req } => {
                    if ledger.is_aborted(req.request_id) {
                        let request_id = req.request_id;
                        self.retire_aborted(request_id, ledger);
                    } else {
                        continued.push(req);
                    }
                }
                PendingEffect::EmitAndFinish {
                    request_id,
                    token,
                    logprob,
                    finish_reason,
                    stop_cause,
                } => {
                    if ledger.is_active(request_id) {
                        if ledger.is_aborted(request_id) {
                            ledger.retire(request_id);
                        } else {
                            ledger.push_tokens(request_id, &[token], &[logprob]);
                            finishes.push((request_id, finish_reason, stop_cause));
                        }
                    }
                    self.tracker.finish(request_id);
                    let _ = self.executor.drop_request(request_id);
                }
                PendingEffect::Promote {
                    state,
                    first_token,
                    logprob,
                } => {
                    let request_id = state.request_id;
                    if ledger.is_aborted(request_id) {
                        self.retire_aborted(request_id, ledger);
                    } else {
                        ledger.push_tokens(request_id, &[first_token], &[logprob]);
                        self.tracker.enter_decode(request_id);
                        self.active.push(state);
                    }
                }
            }
        }
        self.prefilling.splice(0..0, continued);

        if !finishes.is_empty() {
            if self.executor.withholds_finishes() {
                let withheld: Vec<DeferredFinish> = finishes
                    .into_iter()
                    .map(|(request_id, reason, stop_cause)| {
                        ledger.defer_finish_with_cause(request_id, reason, stop_cause)
                    })
                    .collect();
                self.executor.release_finished_events(withheld);
            } else {
                for (request_id, reason, stop_cause) in finishes {
                    ledger.finish_with_cause(request_id, reason, stop_cause);
                }
            }
        }
    }

    fn drain_idle_control(&mut self) {
        while let Some(control) = self.pending_control.pop_front() {
            handle_control_request(&mut self.executor, control);
        }
    }
}

impl<E: ModelExecutor> Scheduler for Qwen3Scheduler<E> {

    pub config: &'a serde_json::Value,
    /// Shared flags (the line reads only its consumed subset).
    pub shared: &'a SharedArgs,
    /// Full parse of the merged command; the line recovers its exclusive
    /// flags with `<Cli as clap::FromArgMatches>::from_arg_matches`.
    pub matches: &'a clap::ArgMatches,
}

/// What the frontend must know before (and independently of) the engine
/// finishing its load.
///
/// Lines should build their plan with `..ServePlan::default()` and spell only
/// what they set: CI compiles three model lines, so an exhaustive literal in
/// any other crate breaks on the next field added here and nothing catches it
/// until that crate is checked by hand.
pub struct ServePlan {
    /// Scheduler partitions (logical DP ranks) the launched engine will
    /// expose. The HTTP frontend registers one engine identity per partition
    /// *while the engine is still loading*, so this must be derivable from
    /// CLI flags alone. Checked against
    /// [`EngineHandle::scheduler_partition_count`] after launch.
    pub scheduler_partition_count: usize,
    /// Serve the prefill-only route contract (GLM5.2 TP4 P/D prefill role).
    pub prefill_only: bool,
    /// `Some` enables the LoRA routes, preloading the listed adapters.
    pub lora_modules: Option<Vec<LoraModule>>,
    /// The parser this line's tool syntax feeds, used when the caller leaves
    /// `--tool-call-parser` at `auto`. Upstream `Auto` matches the model
    /// *path* by substring, so it depends on the directory name; a line whose
    /// checkpoints share one tool format resolves `auto` itself instead.
    pub auto_tool_call_parser: Option<ParserSelection>,
}

impl ServePlan {
    /// The parser the server should run with: an explicit user selection wins;
    /// `auto` falls back to the line's own default when it declares one.
    pub fn resolve_tool_call_parser(&self, requested: ParserSelection) -> ParserSelection {
        match requested {
            ParserSelection::Auto => self
                .auto_tool_call_parser
                .clone()
                .unwrap_or(ParserSelection::Auto),
            explicit => explicit,
        }
    }

